import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side','price','qty','arrival'}
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    arrival = 0

    def clean_buy():
        while buy_heap:
            negprice, arr, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or o['qty'] <= 0 or o['side'] != 'buy':
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or o['qty'] <= 0 or o['side'] != 'sell':
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None:
                o['qty'] = 0
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sp, sarr, soid = sell_heap[0]
                if typ != 'market' and price < sp:
                    break
                so = book[soid]
                trade_qty = min(remaining, so['qty'])
                trades.append([oid, soid, sp, trade_qty])
                remaining -= trade_qty
                so['qty'] -= trade_qty
                if so['qty'] <= 0:
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'arrival': arrival}
                heapq.heappush(buy_heap, (-price, arrival, oid))
                arrival += 1
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negbp, barr, boid = buy_heap[0]
                bp = -negbp
                if typ != 'market' and price > bp:
                    break
                bo = book[boid]
                trade_qty = min(remaining, bo['qty'])
                trades.append([boid, oid, bp, trade_qty])
                remaining -= trade_qty
                bo['qty'] -= trade_qty
                if bo['qty'] <= 0:
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'arrival': arrival}
                heapq.heappush(sell_heap, (price, arrival, oid))
                arrival += 1

    return trades

